import json
from backend.circuit_types import PIN_SCHEMAS

HTML = r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Revisar circuito</title>
<style>body{margin:0;font-family:Arial,sans-serif;background:#f4f6f8;color:#17202a}main{max-width:1250px;margin:auto;padding:22px}p{line-height:1.5}button,.button{background:#1769aa;color:white;border:0;border-radius:6px;padding:11px 14px;cursor:pointer;text-decoration:none;font:inherit}button:disabled{opacity:.45;cursor:default}.secondary{background:#566573}.danger{background:#a93226}.bar{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.card{background:white;border:1px solid #d5dde5;border-radius:8px;padding:18px;margin:18px 0}.status{background:#e7f0f7;padding:15px;white-space:pre-wrap;border-radius:6px}.warn{background:#fff3dc}input,select{font:inherit;padding:8px;border:1px solid #9baaba;border-radius:4px;max-width:100%;box-sizing:border-box}table{border-collapse:collapse;width:100%}td,th{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #ddd}th{white-space:nowrap;background:#f4f6f8}td input{width:125px}td select{width:190px}.scroll{overflow:auto}.pin{display:flex;gap:8px;align-items:center;margin-bottom:6px}.pin span{min-width:34px}.pin input{width:160px}img{max-width:100%;max-height:520px;object-fit:contain}.pictures{display:flex;gap:20px;flex-wrap:wrap}.pictures figure{margin:0}li{line-height:1.5;margin:8px 0}[hidden]{display:none!important}
.circuit-table{table-layout:fixed}.circuit-table th:nth-child(1){width:12%}.circuit-table th:nth-child(2){width:16%}.circuit-table th:nth-child(3){width:29%}.circuit-table th:nth-child(4){width:14%}.circuit-table th:nth-child(5){width:22%}.circuit-table th:nth-child(6){width:7%}.circuit-table td input,.circuit-table td select{width:100%}.circuit-table td,.circuit-table th{padding:12px!important}.circuit-table .model-editor>details{margin-top:10px;padding:4px 10px}.circuit-table .model-editor>small{display:block;font-size:11px;line-height:1.5;margin:6px 0}.circuit-table .pin{gap:6px}.circuit-table .pin span{min-width:26px;font-size:12px}.circuit-table .pin input{width:100%;min-width:0}.value-unit{display:grid;gap:8px}.value-unit label{font-size:11px;color:#647772}.value-unit input{display:block}.circuit-table button.danger{white-space:nowrap;font-size:12px!important;padding:8px!important}.review-tools{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap;margin:18px 0}.review-tools input{width:300px}.review-tools small{color:#647772}.netlist-card pre{margin:16px 0 0;padding:18px;border-radius:10px;background:#f3f6f4;font:12px/1.65 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.netlist-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.netlist-head h2{margin:0}.netlist-status{font-size:13px;color:#647772}.estimated-note{font-size:12px;background:#edf5f0;padding:12px 16px;border-radius:8px}.nets-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;list-style:none;padding:0}.nets-list li{border:1px solid #dce5e0;padding:12px;border-radius:8px;font-size:13px}.simulation-params{width:100%;font-size:12px}.simulation-params td{font-size:12px;line-height:1.7}.circuit-table .reading-note{display:block;padding:6px 8px;background:#fff4df;border-radius:6px;font-size:11px}
@media(max-width:900px){.circuit-table,.circuit-table tbody,.circuit-table tr,.circuit-table td{display:block}.circuit-table thead{display:none}.circuit-table tr{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:16px;margin:16px 0;border:1px solid #dce5e0;border-radius:12px}.circuit-table td{border:0!important;padding:0!important;width:auto!important}.circuit-table td[data-label]::before{content:attr(data-label);display:block;margin-bottom:6px;font-size:12px;color:#647772}.circuit-table td:nth-child(3),.circuit-table td:nth-child(5){grid-column:1/-1}.circuit-table td[hidden],.circuit-table tr[hidden]{display:none!important}}@media(max-width:500px){.circuit-table tr{grid-template-columns:1fr}.circuit-table td{grid-column:1!important}.review-tools input{width:100%}}
</style></head>
<body><main><a id="back">Voltar a redes e circuit.json</a><h1>Revisar circuito</h1><p>Confira a imagem, corrija os componentes e valores e escolha a rede de cada pino. Pinos com o mesmo nome de rede ficam ligados. Para separar uma ligação, atribua nomes diferentes.</p>
<div class="bar"><button id="save" disabled>Salvar revisão</button><button id="confirm" disabled>Confirmar circuito</button><a id="download" class="button secondary" hidden>Baixar circuit.json salvo</a><button id="reload" class="secondary">Descartar edições e recarregar</button><a id="simulation" class="button secondary" hidden>Simular — etapas 13 e 14</a></div><div id="status" class="status" role="status">Carregando...</div>
<div class="card"><label>Nome do circuito <input id="name" maxlength="120"></label><p class="estimated-note">Campos de modelo e parâmetros vazios recebem uma estimativa automática. Seus valores informados têm prioridade. Confira a referência usada antes de continuar.</p><div class="review-tools"><input id="componentSearch" type="search" aria-label="Buscar no circuito" placeholder="Buscar nome, modelo ou componente…"><small id="componentCount"></small></div><div class="scroll"><table class="circuit-table"><thead><tr><th>Nome</th><th>Componente</th><th>Modelo e parâmetros</th><th>Valor e unidade</th><th>Pinos → redes</th><th>Ação</th></tr></thead><tbody id="components"></tbody></table></div><div class="bar"><button id="add" disabled>Adicionar componente</button></div><p>Exemplos de valor: 1000, 10k, 100u, 5. O Falstad usa os valores e conexões confirmados. Ao mudar o tipo, confira novamente o nome e a rede de cada pino.</p><label><input id="ack" type="checkbox"> Conferi os componentes, valores e conexões, incluindo os avisos exibidos.</label></div>
<div class="card"><h2>Conexões do circuito em edição</h2><ul class="nets-list" id="nets"></ul><datalist id="netNames"></datalist></div><div class="card netlist-card"><div class="netlist-head"><h2>Lista de conexões para conferência</h2><button id="refreshNetlist" type="button">Atualizar prévia</button></div><p id="netlistStatus" class="netlist-status" role="status">Preparando a netlist…</p><p class="netlist-status">A prévia acompanha as edições. Salvar e confirmar o circuito continua sendo necessário para simular.</p><pre id="netlist" aria-label="Lista de conexões da revisão"></pre><details open><summary>Componentes, modelos e parâmetros usados na netlist</summary><table class="simulation-params"><thead><tr><th>Componente / modelo</th><th>Parâmetros</th></tr></thead><tbody id="netlistParameters"></tbody></table></details><p id="netlistNodes" class="netlist-status"></p><ul id="netlistWarnings"></ul></div><div class="card"><h2>Avisos da versão salva</h2><ul id="issues"></ul><details><summary>Avisos originais da análise automática</summary><ul id="automatic"></ul></details></div>
<div class="card"><h2>Imagem de referência</h2><p>Estas imagens mostram a detecção automática. As correções desta etapa ficam nas tabelas e no circuit.json; os pontos da imagem não são reposicionados.</p><div class="pictures"><figure><figcaption>Foto original</figcaption><img id="original" alt="Foto original do circuito"></figure><figure><figcaption>Redes detectadas automaticamente</figcaption><img id="preview" alt="Redes da etapa 10"></figure></div></div></main>
<script src="/model-editor.js?v=5.24.0"></script><script id="payload" type="application/json">__PAYLOAD__</script><script>
const config=JSON.parse(document.getElementById('payload').textContent),base='/projects/'+encodeURIComponent(config.project_id),types=config.types;
const labels={resistor:'Resistor',capacitor:'Capacitor',capacitor_polarized:'Capacitor polarizado',inductor:'Indutor',diode:'Diodo',led:'LED',source_dc:'Fonte DC',battery:'Bateria',gnd:'Terra (GND)',vcc:'Alimentação / saída (VCC)',transistor_npn:'Transistor NPN',transistor_pnp:'Transistor PNP',mosfet_n:'MOSFET N',mosfet_p:'MOSFET P',opamp:'Amplificador operacional'};
const el=id=>document.getElementById(id),status=el('status');let state=null,rev='',dirty=false,busy=false;
el('simulation').href=base+'/simulation-view';el('back').href=base+'/circuit-view';el('original').src='/projects-files/'+encodeURIComponent(config.project_id)+'/original.png';el('preview').src='/projects-files/'+encodeURIComponent(config.project_id)+'/connectivity.png';
function message(text,warn=false){status.textContent=text;status.className='status'+(warn?' warn':'')}
function controls(){el('save').disabled=!state||!dirty||busy;el('confirm').disabled=!state||dirty||busy||!el('ack').checked||state.confirmed_by_user;el('add').disabled=!state||busy;el('download').hidden=!state||dirty;el('reload').disabled=busy;el('simulation').hidden=!state?.confirmed_by_user||dirty||busy}
function changed(){dirty=true;el('ack').checked=false;message('Alterações ainda não salvas. Clique em Salvar revisão.');drawNets();controls();schedulePreview()}
function input(value,label,onchange){const field=document.createElement('input');field.value=value||'';field.setAttribute('aria-label',label);field.oninput=()=>{onchange(field.value);changed()};return field}
function destinations(){return Object.fromEntries(state.nets.flatMap(n=>n.members.map(m=>[m,n.name])))}
function drawNets(){if(!state)return;const groups=Object.create(null);for(const c of state.components)for(const pin of c.pins){const net=c.assignments[pin]||'Sem rede';(groups[net]??=[]).push(c.id+'.'+pin)}el('nets').replaceChildren();el('netNames').replaceChildren();for(const [name,members] of Object.entries(groups)){const li=document.createElement('li');li.textContent=name+': '+members.join(', ');el('nets').appendChild(li);const option=document.createElement('option');option.value=name;el('netNames').appendChild(option)}}
function captureEditors(){for(const c of state.components)if(c._editor)c._modelInput=c._editor.read()}
function filterComponents(){const q=el('componentSearch').value.trim().toLocaleLowerCase('pt-BR');let count=0;for(const c of state.components){const code=c._editor?.read().model||c.metadata?.model?.text||'';c._row.hidden=!!q&&![c.id,labels[c.type]||c.type,code].join(' ').toLocaleLowerCase('pt-BR').includes(q);if(!c._row.hidden)count++}el('componentCount').textContent=count+' de '+state.components.length+' componentes'}
function render(){el('components').replaceChildren();el('name').value=state.name;for(const c of state.components){const tr=document.createElement('tr');c._row=tr;function cell(child,label){const td=document.createElement('td');td.dataset.label=label;td.appendChild(child);tr.appendChild(td)}cell(input(c.id,'Identificação de '+c.id,v=>c.id=v),'Nome');const select=document.createElement('select');select.setAttribute('aria-label','Tipo de '+c.id);for(const type of Object.keys(types)){const opt=document.createElement('option');opt.value=type;opt.textContent=labels[type]||type;select.appendChild(opt)}select.value=c.type;select.onchange=()=>{captureEditors();const old=c.pins.map(pin=>c.assignments[pin]);c.type=select.value;c.metadata={};c._modelInput=null;c.pins=[...types[c.type]];c.assignments={};for(let i=0;i<c.pins.length;i++)c.assignments[c.pins[i]]=old[i]||newNet();if(!['resistor','capacitor','capacitor_polarized','inductor','source_dc','battery'].includes(c.type)){c.value=null;c.unit=null}changed();render()};cell(select,'Componente');const meta=c.metadata||{},draft=c._modelInput,model=draft?{text:draft.model,source:draft.model_source}:meta.model;const editor=ModelEditor.create({type:c.type,detection_id:c.original_id||c.id,model,electrical_parameters:draft?.electrical_parameters||meta.electrical_parameters,parameter_policy:draft?.parameter_policy||meta.parameter_policy},'',{allFields:true});c._editor=editor;cell(editor.childElementCount?editor:document.createTextNode('Ideal / sem modelo'),'Modelo e parâmetros');const values=document.createElement('div');values.className='value-unit';for(const [field,label] of [['value','Valor'],['unit','Unidade']]){const wrap=document.createElement('label');wrap.textContent=label;const entry=input(c[field],label+' de '+c.id,v=>c[field]=v);entry.disabled=!['resistor','capacitor','capacitor_polarized','inductor','source_dc','battery'].includes(c.type);entry.placeholder=entry.disabled?'':field==='value'?'Ex.: 10k, 100uF, 5':'Ω, F, H, V';wrap.append(entry);values.append(wrap)}cell(values,'Valor e unidade');const pins=document.createElement('div');for(const pin of c.pins){const line=document.createElement('label');line.className='pin';const text=document.createElement('span');text.textContent=pin;line.appendChild(text);const field=input(c.assignments[pin],'Rede de '+c.id+'.'+pin,v=>c.assignments[pin]=v);field.setAttribute('list','netNames');line.appendChild(field);pins.appendChild(line)}cell(pins,'Pinos → redes');const remove=document.createElement('button');remove.textContent='Remover';remove.className='danger';remove.setAttribute('aria-label','Remover '+c.id);remove.onclick=()=>{captureEditors();state.components=state.components.filter(item=>item!==c);changed();render()};cell(remove,'Ação');el('components').appendChild(tr)}drawNets();filterComponents()}
let previewTimer=null,previewVersion=0;
function schedulePreview(){clearTimeout(previewTimer);const version=++previewVersion;el('netlistStatus').textContent='Atualizando com suas edições…';previewTimer=setTimeout(()=>updatePreview(version),500)}
async function updatePreview(version=++previewVersion){try{const data=await request(base+'/circuit-review/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body())});if(version!==previewVersion)return;el('netlist').textContent=data.netlist||'';el('netlistStatus').textContent=data.ready?'Prévia atualizada com os modelos, valores e conexões acima.':data.message||'Confira os campos para gerar a prévia.';el('netlistParameters').replaceChildren();for(const c of data.circuit?.components||[]){const row=document.createElement('tr'),title=document.createElement('td'),params=document.createElement('td');const binding=data.components?.find(b=>b.component_id===c.id);title.textContent=c.id+' · '+(c.metadata?.model?.text||'ideal');if(c.value){const v=document.createElement('div');v.textContent='Valor: '+c.value+(c.unit?' '+c.unit:'');params.append(v)}for(const [key,p] of Object.entries(c.metadata?.electrical_parameters||{})){const line=document.createElement('div');const label=key==='gate_drive_voltage'&&p.estimated?'referência do ensaio':{manual:'informado por você',ocr:'OCR',datasheet_typical:'típico',datasheet_midpoint:'ponto médio',datasheet_derived:'estimativa calculada'}[p.source]||p.source;line.textContent=((ModelEditor.definition(key)?.label||key)+': '+Number(Number(p.value).toPrecision(6))+' '+p.unit+' · '+label+(p.datasheet?.reference_only?' · referência: '+p.datasheet.model:''));params.append(line)}row.append(title,params);el('netlistParameters').append(row)}el('netlistNodes').textContent='Redes: '+Object.entries(data.nodes||{}).map(([name,node])=>name+' → '+node).join(' · ');el('netlistWarnings').replaceChildren();for(const warning of data.warnings||[]){const li=document.createElement('li');li.textContent=warning;el('netlistWarnings').append(li)}}catch(error){if(version===previewVersion){el('netlist').textContent='';el('netlistStatus').textContent=error.message}}}
el('refreshNetlist').onclick=()=>updatePreview();el('componentSearch').oninput=filterComponents;el('components').addEventListener('input',e=>{if(e.target.closest('.model-editor'))changed()});el('components').addEventListener('change',e=>{if(e.target.closest('.model-editor'))changed()});
function newNet(){const used=new Set(state.components.flatMap(c=>Object.values(c.assignments||{})));let i=1;while(used.has('NET_MANUAL_'+i))i++;return 'NET_MANUAL_'+i}
function warnings(parent,items){el(parent).replaceChildren();for(const item of items){const li=document.createElement('li');li.textContent=(item.component_id||item.terminal_ref||item.net||'Circuito')+': '+item.message+(item.blocking?' (corrigir antes de confirmar)':'');el(parent).appendChild(li)}if(!items.length){const li=document.createElement('li');li.textContent='Nenhum aviso nesta lista.';el(parent).appendChild(li)}}
async function request(url,options){const r=await fetch(url,options),data=await r.json();if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'Não foi possível concluir a operação.');return data}
async function load(){const [,data]=await Promise.all([ModelEditor.init(''),request(base+'/circuit-review')]);state=data.circuit;rev=data.revision;const dest=destinations();for(const c of state.components){c.original_id=c.id;c.assignments=Object.fromEntries(c.pins.map(pin=>[pin,dest[c.id+'.'+pin]||'']))}dirty=false;el('ack').checked=false;render();warnings('issues',data.issues);warnings('automatic',state.review?.automatic_warnings||state.warnings||[]);el('download').href=base+'/circuit/download';if(data.original_filename)el('original').src='/projects-files/'+encodeURIComponent(config.project_id)+'/'+encodeURIComponent(data.original_filename);schedulePreview();message(state.confirmed_by_user?'Circuito confirmado pelo usuário. Qualquer nova edição exige salvar e confirmar novamente.':'Circuito não confirmado. Confira, salve as correções e confirme a revisão.');controls()}
function body(){const groups=Object.create(null);const components=state.components.map(c=>{for(const pin of c.pins){const net=(c.assignments[pin]||'').trim();if(!net)throw new Error('Informe a rede de '+c.id+'.'+pin);(groups[net]??=[]).push(c.id+'.'+pin)}return {id:c.id.trim(),original_id:c.original_id,type:c.type,value:c.value,unit:c.unit,pins:c.pins,...c._editor.read()}});return {base_revision:rev,name:el('name').value,components,nets:Object.entries(groups).map(([name,members])=>({name,members}))}}
async function run(action){busy=true;controls();try{const payload=action==='save'?body():{base_revision:rev,acknowledge_warnings:el('ack').checked};await request(base+'/circuit-review'+(action==='confirm'?'/confirm':''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await load();message(action==='confirm'?'Circuito confirmado. O JSON salvo contém a revisão humana.':'Revisão salva. Confira os avisos antes de confirmar.');return true}catch(e){message(e.message,true);return false}finally{busy=false;controls()}}
el('save').onclick=()=>run('save');el('confirm').onclick=()=>run('confirm');el('ack').onchange=controls;el('name').oninput=changed;el('reload').onclick=()=>{load().catch(e=>message(e.message,true))};
el('add').onclick=()=>{captureEditors();let i=1;while(state.components.some(c=>c.id==='X'+i))i++;const c={id:'X'+i,original_id:null,type:'resistor',value:null,unit:null,pins:['1','2'],assignments:{}};state.components.push(c);for(const pin of c.pins)c.assignments[pin]=newNet();changed();render()};
window.GuidedReady=load().then(()=>true).catch(e=>{message(e.message+' Abra Redes e circuit.json e gere a etapa 11 primeiro.',true);controls();return false});
</script></body></html>'''

def review_page(project_id):
    payload=json.dumps(dict(project_id=project_id,types=PIN_SCHEMAS),ensure_ascii=False).replace("<","\\u003c")
    return HTML.replace("__PAYLOAD__",payload)
